//! `Crls::parse` (`[tls] crl`, loaded at startup and on every SIGHUP): a
//! CRL file and the client CA certificates, through x509-parser and every
//! check the server adds. It must never panic, whatever the file holds.
//!
//! The first byte picks what the rest is:
//! - 0: one CRL's DER, checked against the fixture CA (`fixtures/ca.der`,
//!   which signed the seeds' CRLs; regenerated by the `seeds` example);
//! - 1: the CRL file's text as is (PEM framing, several CRLs);
//! - 2: a client CA certificate's DER, with the fixture CRL.
#![no_main]

use base64::Engine as _;
use base64::engine::general_purpose::STANDARD;
use ferritor_server::crl::Crls;
use libfuzzer_sys::fuzz_target;
use rustls_pki_types::CertificateDer;

const CA: &[u8] = include_bytes!("../fixtures/ca.der");
const CRL: &[u8] = include_bytes!("../fixtures/crl.der");

fn pem(der: &[u8]) -> Vec<u8> {
    let body = STANDARD.encode(der);
    let lines: Vec<&str> = body
        .as_bytes()
        .chunks(64)
        .map(|chunk| std::str::from_utf8(chunk).unwrap_or_default())
        .collect();
    format!(
        "-----BEGIN X509 CRL-----\n{}\n-----END X509 CRL-----\n",
        lines.join("\n")
    )
    .into_bytes()
}

fuzz_target!(|data: &[u8]| {
    let Some((&mode, rest)) = data.split_first() else {
        return;
    };
    let (file, ca) = match mode % 3 {
        0 => (pem(rest), CA),
        1 => (rest.to_vec(), CA),
        _ => (pem(CRL), rest),
    };
    let cas = [CertificateDer::from(ca)];
    if let Ok(crls) = Crls::parse(&file, &cas) {
        // One CRL per client CA, and every client CA has one.
        assert_eq!(crls.info().len(), cas.len());
        assert_eq!(crls.ders().len(), cas.len());
    }
});
